void drawLogoUMS(TFT_eSPI &tft, int x, int y) {
  uint32_t index = 0;
  for (int yy = 0; yy < LOGO_UMS_HEIGHT; yy++) {
    for (int xx = 0; xx < LOGO_UMS_WIDTH; xx++) {
      uint8_t r = pgm_read_byte(&logo_ums_rgb888[index++]);
      uint8_t g = pgm_read_byte(&logo_ums_rgb888[index++]);
      uint8_t b = pgm_read_byte(&logo_ums_rgb888[index++]);
      uint16_t warna = tft.color565(r, g, b);
      tft.drawPixel(x + xx, y + yy, warna);
    }
  }
}
